local GrocerySyncPVPNode = Class("GrocerySyncPVPNode", Base)

--region lifecycle
function GrocerySyncPVPNode:__init()
    Base.__init(self)
    
    self._rank = nil -- 排位段位
end

function GrocerySyncPVPNode:__delete()
    Base.__delete(self)

    self._rank = nil
end

function GrocerySyncPVPNode:Start()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = Bind(self, self.Update)
        self._behaviourAction = behaviourAction
    end
end

function GrocerySyncPVPNode:Update()
    self:UpdateTopTabUI()
end

function GrocerySyncPVPNode:OnDestroy()
    if self._behaviourAction then
        self._behaviourAction.UpdateAction = nil
        self._behaviourAction = nil
    end
    Base.OnDestroy(self)
end
