--region override
---初始化杂货铺列表数据
function GrocerySyncPVPNode:InitGroceryData()
    local data = GroceryMgr:GetLadderData()
    local productData = {}
    for _, v in ipairs(data.products) do
        if productData[checkInt(v.tab)] then
            table.insert(productData[checkInt(v.tab)], v)
        else
            productData[checkInt(v.tab)] = {v}
        end
    end
    local groceryData = {}
    for i, v in ipairs(productData) do
        groceryData[i] = {
            products = v,
            text     = GroceryConstants.SyncPVPTapTitle[i]
        }
    end
    return groceryData
end

---初始化顶部页签
function GrocerySyncPVPNode:InitTopTabState()
    return true
end

---初始化杂货铺类型
function GrocerySyncPVPNode:InitGroceryType()
    return GroceryConstants.GroceryType.SyncPVP
end

---初始化刷新定时器
function GrocerySyncPVPNode:InitRefreshTimer()
    local data = GroceryMgr:GetLadderData()
    return data.nextRefreshLeftSeconds
end

---初始化顶部页签
function GrocerySyncPVPNode:InitTopTab()
    local tabState = self:GetTabState()
    CfUtils.SetActive(self.TabScrollView, tabState)
    if not tabState then return end
    
    self:SetSelectedTab(1)
    local groceryData = self:GetGroceryData()
    if not self.TabScrollView.IsListViewInit then
        self.TabScrollView:InitGridView(#groceryData, Bind(self, self.OnTabGetItemByIndex))
    else
        GameUtils.ReloadData(self.TabScrollView, #groceryData)
        self.TabScrollView:MovePanelToItemByIndex(0)
    end
    
end

---页签列表刷新
function GrocerySyncPVPNode:OnTabGetItemByIndex(listView, idx)
    if idx < 0 then return nil end

    local cell = listView:NewListViewItem("Cell")
    ---@type CommonTabToggleUpCell
    local nodeScr = CfUtils.GetLuaScr(cell, GroceryConstants.ScrPath.CommonTabToggleUpCell)
    if isNull(nodeScr) then return nil end

    local index = idx + 1
    local data = self:GetGroceryData()[index]
    nodeScr:FreshBaseUI(data)
    local isSelected = index == self:GetSelectedTab()
    nodeScr:FreshSelectStatus(isSelected)
    nodeScr:SetLockStatus(isSelected and 2 or 1)
    nodeScr:SetCallBack(function() --点击回调
        if index ~= self:GetSelectedTab() then --屏蔽掉重复点击当前选择的toggle
            nodeScr:FreshSelectStatus(true)
            nodeScr:SetLockStatus(2)
            local preNodeGo = self.TabScrollView:GetShownItemByItemIndex(self:GetSelectedTab() - 1)
            if not isNull(preNodeGo) then
                ---@type CommonTabToggleUpCell
                local preNodeScr = CfUtils.GetLuaScr(preNodeGo, GroceryConstants.ScrPath.CommonTabToggleUpCell)
                preNodeScr:FreshSelectStatus(false)
                preNodeScr:SetLockStatus(1)
            end
            self:SetSelectedTab(index)
            self:RefreshUI()
            self:PlaySwitchTabAnimation()
        end
    end)
    nodeScr:SetLockState(index > self:GetRank())
    
    return cell
end

function GrocerySyncPVPNode:InitData()
    Base.InitData(self)
    
    self:InitRank()
end

function GrocerySyncPVPNode:InitHandler()
    Base.InitHandler(self)

    SetButtonAction(self.Left, Bind(self, self.TabBtnLeftOnClickHandler))
    SetButtonAction(self.Right, Bind(self, self.TabBtnRightOnClickHandler))
end

---cell点击回调
function GrocerySyncPVPNode:GroceryCellOnClickHandler(index)
    if not self:CheckRank() then
        GameUtils.Toast(localize("提升段位可解锁"))
        return 
    end
    
    Base.GroceryCellOnClickHandler(self, index)
end

---刷新UI
function GrocerySyncPVPNode:RefreshUI()
    Base.RefreshUI(self)

    self:RefreshLockState()
end
--endregion override

--region init
---初始化段位
function GrocerySyncPVPNode:InitRank()
    local data = GroceryMgr:GetLadderData()
    self:SetRank(data.segment)
end
--endregion init

--region handler
---顶部页签左侧按钮点击回调
function GrocerySyncPVPNode:TabBtnLeftOnClickHandler()
    self.TabScrollView:MovePanelToItemByIndex(0)
end

---顶部页签右侧按钮点击回调
function GrocerySyncPVPNode:TabBtnRightOnClickHandler()
    self.TabScrollView:MovePanelToItemByIndex(#self:GetGroceryData())
end
--endregion handler

--region public
---刷新页面
function GrocerySyncPVPNode:Refresh()
    self:InitData()
    self:InitUI()
    self:RefreshUI()
    self:PlayEnterAnimation()
end

---刷新货币栏
function GrocerySyncPVPNode:RefreshCurrencyBar()
    local currencyList = GroceryUtils.GetCurrencyByGroceryType(self:GetGroceryType())
    if not currencyList then
        currencyList = {Constants.Currency.FreeDiamondId}
    end
    CfUtils.RefreshTopGoods(currencyList)
end
--endregion public

--region private
---播放进入动画
function GrocerySyncPVPNode:PlayEnterAnimation()
    self.Root:Stop()
    CfUtils.PlayAnimation(self.Root, "OverseaStoreSynchronousPvpDialog_L")
end

---播放进入动画
function GrocerySyncPVPNode:PlaySwitchTabAnimation()
    self.Root:Stop()
    CfUtils.PlayAnimation(self.Root, "OverseaStoreSynchronousPvpDialog_T")
end

---检查商品rank要求是否达到
---@return boolean 是否满足
function GrocerySyncPVPNode:CheckRank()
    local tab = self:GetSelectedTab()
    local rank = self:GetRank()
    return rank >= tab
end

---更新顶部页签UI
function GrocerySyncPVPNode:UpdateTopTabUI()
    local posX = self.Content.localPosition.x
    local viewportW = self.Viewport.rect.width
    local contentW = self.Content.rect.width
    CfUtils.SetActive(self.Left, posX < 0)
    CfUtils.SetActive(self.Right, contentW - viewportW + posX> 0)
end

---刷新锁定状态
function GrocerySyncPVPNode:RefreshLockState()
    if self:CheckRank() then
        CfUtils.SetActive(self.Lock, false)
    else
        CfUtils.SetActive(self.Lock, true)
        local data = self:GetGroceryData()[self:GetSelectedTab()]
        CfUtils.FillText(self.LockTextDesc, localize("段位达到_name_解锁", {_name_ = data.text}))
    end
end
--endregion private

